import { type StrategyType, DEFAULT_STRATEGY_ORDER, StrategyState } from '../state/strategy-state.js'
import type { StrategyWeightKey, ExperienceStore } from '../state/experience-store.js'
import type { FailureDiagnostics } from '../state/failure-diagnostics.js'
import { TaskGraph } from '../state/task-graph.js'
import type { Task } from '../state/task-graph.js'
import type { WorldModel } from '../state/world-model.js'
import type { CallerState } from '../state/caller-state.js'
import type { SupervisorDirective } from '../supervisor.js'

export type ReplanScope = 'LOCAL' | 'GLOBAL'

export interface RollbackReplanResult {
  rolledBack: boolean
  cannotProgress: boolean
  newStrategyState: StrategyState
  newTaskGraph: TaskGraph
  replanScope: ReplanScope | null
  /**
   * Set only when failureModeHint (not the supervisor's redirectHint) picked the next strategy —
   * see harness-runtime.ts's onFailureModeSwitch. The bias alone changes bookkeeping only
   * (current_strategy, switch_triggers); nothing in this harness reads a task's chosen strategy
   * during execution, so this is what lets a host surface the classification to the proposer as
   * something to actually act on.
   */
  failureModeSwitch?: { failure_class: string; strategy: StrategyType }
  /**
   * Set only when the experience-learning feed (HarnessRunOptions.experienceLearning) re-ranked the ladder for this failure
   * class and that ranking picked the next strategy (no supervisor redirect, no failure-mode bias). Like failureModeSwitch it is
   * bookkeeping unless the host surfaces it to the proposer — nothing in this harness reads a task's chosen strategy.
   */
  learnedSwitch?: { failure_class: string; strategy: StrategyType }
}

export const STALL_WINDOW = 5
export const MAX_SWITCHES = 3
export const RECURRENCE_THRESHOLD = 3
export const OSCILLATION_WINDOW = 6

const CAUTIOUS_THRESHOLD = 1  // index in NORMAL(0) < CAUTIOUS(1) < BLOCKED(2)
const RISK_ORDER: Record<string, number> = { NORMAL: 0, CAUTIOUS: 1, BLOCKED: 2 }

function stalledCompletion(strategyState: StrategyState): boolean {
  const history = strategyState.completion_history
  if (history.length < STALL_WINDOW) return false
  const window = history.slice(-STALL_WINDOW)
  return new Set(window).size === 1
}

function strategyLooping(strategyState: StrategyState): boolean {
  if (strategyState.switch_count <= MAX_SWITCHES) return false
  const history = strategyState.completion_history
  if (history.length === 0) return true
  return history[history.length - 1] === history[0]
}

function failureRecurring(failureDiagnostics: FailureDiagnostics): boolean {
  const history = failureDiagnostics.failure_history
  if (history.length < RECURRENCE_THRESHOLD) return false
  const recent = history.slice(-RECURRENCE_THRESHOLD)
  const classes = recent.map(e => e.failure_class)
  return new Set(classes).size === 1 && classes[0] !== undefined && classes[0] !== ''
}

function riskOscillating(strategyState: StrategyState): boolean {
  const history = strategyState.risk_state_history
  if (history.length < OSCILLATION_WINDOW) return false
  const window = history.slice(-OSCILLATION_WINDOW)
  const levels = window.map(r => RISK_ORDER[r] ?? 0)
  let alternations = 0
  for (let i = 1; i < levels.length; i++) {
    const prevBelowCaution = levels[i - 1] < CAUTIOUS_THRESHOLD
    const curBelowCaution = levels[i] < CAUTIOUS_THRESHOLD
    if (prevBelowCaution !== curBelowCaution) alternations++
  }
  return alternations >= 2
}

export function cannotMakeProgress(
  strategyState: StrategyState,
  failureDiagnostics: FailureDiagnostics,
): boolean {
  if (stalledCompletion(strategyState)) {
    strategyState.stall_reason = 'completion_velocity'
    return true
  }
  if (strategyLooping(strategyState)) {
    strategyState.stall_reason = 'strategy_loop'
    return true
  }
  if (failureRecurring(failureDiagnostics)) {
    strategyState.stall_reason = 'failure_recurrence'
    return true
  }
  if (riskOscillating(strategyState)) {
    strategyState.stall_reason = 'risk_oscillation'
    return true
  }
  strategyState.stall_reason = ''
  return false
}

function softmax(values: number[]): number[] {
  const max = Math.max(...values)
  const exps = values.map(v => Math.exp(v - max))
  const total = exps.reduce((a, b) => a + b, 0)
  return exps.map(e => e / total)
}

export function buildStrategyOrdering(
  failureClass: string,
  experienceStore: ExperienceStore,
  _currentStrategy?: StrategyType,
): StrategyType[] {
  if (!experienceStore.available) return [...DEFAULT_STRATEGY_ORDER]

  const weights = experienceStore.getStrategyWeights()
  const classWeights: number[] = DEFAULT_STRATEGY_ORDER.map(s => {
    const key: StrategyWeightKey = `${s}:${failureClass}`
    return weights[key] ?? 0
  })

  if (classWeights.every(v => v === 0)) return [...DEFAULT_STRATEGY_ORDER]

  const probs = softmax(classWeights)
  const indexed = DEFAULT_STRATEGY_ORDER.map((s, i) => ({ s, p: probs[i] }))
  indexed.sort((a, b) => b.p - a.p)
  return indexed.map(x => x.s)
}

const sameOrder = (a: readonly string[], b: readonly string[]): boolean => a.length === b.length && a.every((v, i) => v === b[i])

/**
 * The next strategy from a LEARNED ranking. `getNextStrategy` takes the entry after the current strategy, which is right for the
 * fixed default order but, for a ranking, skips the top choice whenever the current strategy sits above it (current DIRECT_EDIT
 * with [BROADER_SEARCH, TRACE_EXEC, DIRECT_EDIT, …] would land on the fourth entry). Here the nth switch takes the nth-ranked
 * strategy, stepping past the one already in effect, so the learned winner is tried first and later switches walk down the ranking.
 */
export function pickLearnedStrategy(ordering: StrategyType[], current: StrategyType, switchCount: number): StrategyType {
  const i = Math.min(switchCount, ordering.length - 1)
  const candidate = ordering[i]
  return candidate === current ? ordering[Math.min(i + 1, ordering.length - 1)] : candidate
}

function getNextStrategy(current: StrategyType, ordering: StrategyType[]): StrategyType {
  const idx = ordering.indexOf(current)
  const nextIdx = Math.min(idx + 1, ordering.length - 1)
  return ordering[nextIdx]
}

function diagnoseAndReplan(currentTask: Task, taskGraph: TaskGraph): TaskGraph {
  const currentId = currentTask.id
  for (const task of taskGraph.tasks) {
    if (task.depends_on.includes(currentId) && task.status !== 'COMPLETE') {
      task.status = 'PENDING'
    }
  }
  taskGraph.tasks = taskGraph.tasks.filter(
    t => !(t.status === 'FAILED' && t.depends_on.includes(currentId)),
  )
  taskGraph.changed = true
  return taskGraph
}

/** Flip FAILED leaf tasks (no non-FAILED task depends on them) back to PENDING.
 *  Trajectory Supervisor lever 1 (S8) — twin of replanning.py's requeue_failed_leaves.
 *  A REDIRECT_STRATEGY directive or a completed GATHER_EVIDENCE investigation is a
 *  "retry this task differently" signal, but diagnoseAndReplan (LOCAL) only re-queues
 *  *dependents* of the failed task — on a one-node turn graph nothing lands PENDING and
 *  the redirect / new evidence is never applied. Re-queueing the failed leaf itself
 *  closes that loop. Bounded by the caller (recovery budget, switch_count, cap K).
 *  Returns true iff at least one task was re-queued. */
export function requeueFailedLeaves(taskGraph: TaskGraph): boolean {
  const idsWithLiveDependents = new Set<string>()
  for (const t of taskGraph.tasks) {
    if (t.status !== 'FAILED') for (const dep of t.depends_on) idsWithLiveDependents.add(dep)
  }
  let changed = false
  for (const t of taskGraph.tasks) {
    if (t.status === 'FAILED' && !idsWithLiveDependents.has(t.id)) {
      t.status = 'PENDING'
      changed = true
    }
  }
  if (changed) taskGraph.changed = true
  return changed
}

/** Flip ONE failed task (by id) back to PENDING — even one with dependents (diagnoseAndReplan already reset those to PENDING; they
 *  cannot run until it does). Used for a confident failure-mode match: the classified failure is this task's, so this task gets
 *  the new strategy's attempt. Returns true iff it was FAILED and is now PENDING. */
export function requeueFailedTask(taskGraph: TaskGraph, taskId: string): boolean {
  const t = taskGraph.tasks.find(x => x.id === taskId)
  if (!t || t.status !== 'FAILED') return false
  t.status = 'PENDING'
  taskGraph.changed = true
  return true
}

/** Flip EVERY FAILED task back to PENDING (retryFailedTask). Unlike requeueFailedLeaves this includes a failed task that has
 *  dependents: those dependents were reset to PENDING by diagnoseAndReplan but cannot run while the task they depend on is still
 *  FAILED, so leaving it failed strands the whole chain. Returns true iff at least one task was re-queued. */
export function requeueFailedTasks(taskGraph: TaskGraph): boolean {
  let changed = false
  for (const t of taskGraph.tasks) {
    if (t.status === 'FAILED') {
      t.status = 'PENDING'
      changed = true
    }
  }
  if (changed) taskGraph.changed = true
  return changed
}

function validateTaskGraph(taskGraph: TaskGraph): string[] {
  const errors: string[] = []
  const ids = new Set(taskGraph.tasks.map(t => t.id))
  for (const task of taskGraph.tasks) {
    for (const dep of task.depends_on) {
      if (!ids.has(dep)) errors.push(`Task "${task.id}" depends on unknown task "${dep}"`)
    }
  }
  return errors
}

function rebuildTaskGraph(worldModel: WorldModel, callerState: CallerState, planNote?: string | null): TaskGraph {
  const successCriteria = [...(callerState.success_criteria ?? [])]
  // Trajectory Supervisor REFRAME_PLAN (S2) — an extra reframing constraint.
  if (planNote) successCriteria.push(`Reframe: ${planNote}`)
  const newTasks = successCriteria.map((criterion: string, i: number) => ({
    id: `rebuilt-task-${i}-${Math.random().toString(36).slice(2, 6)}`,
    description: String(criterion),
    status: 'PENDING' as const,
    risk_level: 'MEDIUM' as const,
    depends_on: [],
    parallel_write_domains: [],
    abstraction_level: 1,
    assigned_strategy: null,
  }))

  const beliefTasks = worldModel.beliefs.slice(0, 5).map((belief, i) => ({
    id: `belief-verify-${i}-${Math.random().toString(36).slice(2, 6)}`,
    description: `Verify: ${belief.statement.slice(0, 120)}`,
    status: 'PENDING' as const,
    risk_level: 'LOW' as const,
    depends_on: [],
    parallel_write_domains: [],
    abstraction_level: 2,
    assigned_strategy: null,
  }))

  return new TaskGraph({ tasks: [...newTasks, ...beliefTasks], changed: true })
}

/** Mirrors adapter/harness/recovery.py's apply_failure_mode_bias() threshold. */
const FAILURE_MODE_BIAS_MIN_CONFIDENCE = 0.7

export function rollbackAndReplan(
  currentTask: Task,
  strategyState: StrategyState,
  failureDiagnostics: FailureDiagnostics,
  taskGraph: TaskGraph,
  worldModel: WorldModel,
  callerState: CallerState,
  experienceStore: ExperienceStore | null,
  rollbackFn?: () => void,
  supervisorDirective?: SupervisorDirective | null,
  requeueLeafOnLocal = false,
  learnedLadder = false,
  retryFailedTask = false,
): RollbackReplanResult {
  // Rollback
  rollbackFn?.()

  // Record failure
  failureDiagnostics.failure_history.push({
    id: `fail-${Math.random().toString(36).slice(2, 8)}`,
    timestamp: new Date().toISOString(),
    failure_class: failureDiagnostics.matched_pattern?.failure_class ?? 'unknown',
    description: `Task failed: ${currentTask.description}`,
    context: { task_id: currentTask.id },
  })

  const noProgress = cannotMakeProgress(strategyState, failureDiagnostics)
  const failureClass = failureDiagnostics.matched_pattern?.failure_class ?? ''

  // ── Trajectory Supervisor (S2) — a directive threaded in from driveMainLoop after
  // the async supervisorDecider ran on this stall. Only REDIRECT_STRATEGY / REFRAME_PLAN
  // are acted on; CONTINUE and any not-yet-wired action fall through to the plain ladder.
  const isReframe =
    supervisorDirective?.action === 'REFRAME_PLAN' && !!supervisorDirective.plan_note
  const redirectHint =
    !isReframe &&
    supervisorDirective?.action === 'REDIRECT_STRATEGY' &&
    supervisorDirective.strategy_hint &&
    (DEFAULT_STRATEGY_ORDER as readonly string[]).includes(supervisorDirective.strategy_hint)
      ? (supervisorDirective.strategy_hint as StrategyType)
      : null

  // Failure-mode bias — mirrors adapter/harness/recovery.py's apply_failure_mode_bias(): a
  // confident match (>= 0.7, same threshold as Python) whose curated entry names a preferred
  // strategy (strategy_affinity) jumps straight to it instead of walking the ordering one step
  // at a time. Advisory, same as the supervisor's redirect — and lower precedence than it: the
  // supervisor already reasoned about this specific stall with an LLM call, where this is a
  // static lookup from a curated pattern.
  const failureModeHint =
    !redirectHint && !isReframe && failureDiagnostics.matched_pattern &&
    failureDiagnostics.matched_pattern.confidence >= FAILURE_MODE_BIAS_MIN_CONFIDENCE &&
    failureDiagnostics.matched_pattern.strategy_affinity &&
    (DEFAULT_STRATEGY_ORDER as readonly string[]).includes(failureDiagnostics.matched_pattern.strategy_affinity)
      ? failureDiagnostics.matched_pattern.strategy_affinity
      : null

  let ordering: StrategyType[]
  if (experienceStore !== null && experienceStore.available) {
    ordering = buildStrategyOrdering(failureClass, experienceStore, strategyState.current_strategy)
  } else {
    ordering = [...DEFAULT_STRATEGY_ORDER]
  }

  const supTrigger = (tag: string): string =>
    `supervisor:${tag} ${supervisorDirective?.rationale ?? ''}`.trim().slice(0, 200)

  let newStrategyState: StrategyState
  let failureModeSwitch: RollbackReplanResult['failureModeSwitch']
  let learnedSwitch: RollbackReplanResult['learnedSwitch']
  if (isReframe) {
    // REFRAME does not advance the strategy ladder (parity with loop.py's S1 behaviour).
    newStrategyState = new StrategyState({
      ...strategyState.toJSON(),
      switch_triggers: [...strategyState.switch_triggers, supTrigger('REFRAME_PLAN')],
      completion_history: [...strategyState.completion_history],
      risk_state_history: [...strategyState.risk_state_history],
    })
  } else {
    // A ranking learned from earlier runs (experienceLearning on, weights for this class) outranks a curated failure-mode
    // match — it is empirical where the curated affinity is a static lookup — but never the supervisor's redirect, which
    // reasoned about this specific stall.
    const learnedRanking = learnedLadder && !redirectHint && !sameOrder(ordering, DEFAULT_STRATEGY_ORDER)
    const nextStrategy =
      redirectHint ??
      (learnedRanking
        ? pickLearnedStrategy(ordering, strategyState.current_strategy, strategyState.switch_count)
        : (failureModeHint ?? getNextStrategy(strategyState.current_strategy, ordering)))
    learnedSwitch = learnedRanking ? { failure_class: failureClass, strategy: nextStrategy } : undefined
    failureModeSwitch =
      !redirectHint && !learnedRanking && failureModeHint && failureDiagnostics.matched_pattern
        ? { failure_class: failureDiagnostics.matched_pattern.failure_class, strategy: failureModeHint }
        : undefined
    newStrategyState = new StrategyState({
      ...strategyState.toJSON(),
      current_strategy: nextStrategy,
      switch_count: strategyState.switch_count + 1,
      switch_triggers: [
        ...strategyState.switch_triggers,
        redirectHint
          ? supTrigger('REDIRECT_STRATEGY')
          : learnedRanking
            ? `learned:${failureClass || 'unmatched'} -> ${nextStrategy}`
          : failureModeHint
            ? `failure_mode:${failureDiagnostics.matched_pattern?.failure_class} -> ${failureModeHint}`
            : `task_failed: ${currentTask.id}`,
      ],
      stall_reason: strategyState.stall_reason,
      completion_history: [...strategyState.completion_history],
      risk_state_history: [...strategyState.risk_state_history],
    })
  }

  // Determine replan scope and replan
  let newTaskGraph: TaskGraph
  let replanScope: ReplanScope | null = null

  if (isReframe) {
    replanScope = 'GLOBAL'
    newTaskGraph = rebuildTaskGraph(worldModel, callerState, supervisorDirective!.plan_note)
    const errors = validateTaskGraph(newTaskGraph)
    if (errors.length > 0) {
      throw new Error(`Rebuilt task graph is invalid: ${errors.join('; ')}`)
    }
  } else if (noProgress) {
    replanScope = 'GLOBAL'
    newTaskGraph = rebuildTaskGraph(worldModel, callerState)
    const errors = validateTaskGraph(newTaskGraph)
    if (errors.length > 0) {
      throw new Error(`Rebuilt task graph is invalid: ${errors.join('; ')}`)
    }
  } else {
    replanScope = 'LOCAL'
    newTaskGraph = diagnoseAndReplan(currentTask, taskGraph)
    // Trajectory Supervisor lever 1 (S8) — the supervisor asked to retry this task
    // (REDIRECT_STRATEGY, or a completed GATHER_EVIDENCE investigation). diagnoseAndReplan
    // only re-queued dependents, so if that left nothing runnable (one-node turn graph),
    // re-queue the failed leaf so the redirect / new evidence actually gets an attempt.
    // A confident failure-mode-biased switch (failureModeSwitch, computed above) earns the
    // same requeue on its own — a curated pattern match is as good a reason to give this leaf
    // one more attempt as a supervisor directive is, and without it the classification + bias
    // + retry-hint chain has a real decision but nothing left PENDING to apply it to.
    // retryFailedTask (HarnessRunOptions, off by default): the switch above only helps if the failed task runs again under the
    // new strategy, so re-queue every failed task — not just leaves, and not just when nothing else is pending. The ladder's
    // MAX_SWITCHES and the stall rule still bound the retries.
    if (retryFailedTask) {
      if (requeueFailedTasks(newTaskGraph)) newStrategyState.switch_triggers.push(`retry_failed_task: ${currentTask.id}`)
    } else {
      // A confident failure-mode match re-queues the task that failed — on a decomposed turn too, where the old "only when nothing
      // else is pending, and only a leaf" rule never applied (a failed root has dependents, and its siblings are pending), so the
      // classification + bias + retry-hint chain chose a strategy for a task that was then never run again.
      let requeued = false
      if (failureModeSwitch && requeueFailedTask(newTaskGraph, currentTask.id)) {
        requeued = true
        newStrategyState.switch_triggers.push(`failure_mode:requeue_task ${failureModeSwitch.failure_class}`.slice(0, 200))
      }
      if (!requeued && requeueLeafOnLocal && !newTaskGraph.tasks.some(t => t.status === 'PENDING')) {
        if (requeueFailedLeaves(newTaskGraph)) {
          newStrategyState.switch_triggers.push(
            `supervisor:requeue_leaf ${supervisorDirective?.rationale ?? ''}`.trim().slice(0, 200),
          )
        }
      }
    }
  }

  return {
    rolledBack: true,
    cannotProgress: noProgress,
    newStrategyState,
    newTaskGraph,
    replanScope,
    failureModeSwitch,
    learnedSwitch,
  }
}
