function toCheckpoint(ctx: LoopContext): HarnessCheckpoint {
  const runState = new HarnessRunState({
    worldModel: ctx.worldModel,
    callerState: ctx.callerState,
    controlState: ctx.controlState,
    diagnostics: ctx.diagnostics,
    taskGraph: ctx.taskGraph,
    outputContract: ctx.outputContract,
    evidenceStore: ctx.evidenceStore,
    hypothesisSet: ctx.hypothesisSet,
    memoryState: ctx.memoryState,
    strategyState: ctx.strategyState,
    failureDiagnostics: ctx.failureDiagnostics,
    experienceStore: ctx.experienceStore,
    beliefDepGraph: ctx.beliefDepGraph,
  }).toJSON()

  const runConfig: HarnessRunConfigData = {
    objective: ctx.objective,
    successCriteria: ctx.successCriteria,
    maxSteps: ctx.maxSteps,
    depGraphBudget: ctx.depGraphBudget.toJSON(),
    processConceptId: ctx.processConceptId,
  }

  const progress: HarnessRunProgressData = {
    stepsUsed: ctx.stepsUsed,
    nodeExecutionOrder: [...ctx.nodeExecutionOrder],
    finalResult: ctx.finalResult,
    consecutiveReviewFailures: [...ctx.consecutiveReviewFailures.entries()],
    propagationQueue: { reopenedTaskIds: [...ctx.propagationQueue.reopenedTaskIds] },
    pendingProposal: ctx.pendingProposal ?? null,
    pendingReviewerVerdict: ctx.pendingReviewerVerdict ?? null,
    supervisorAskUserCount: ctx.supervisorAskUserCount,
  }

  return { runId: ctx.runId, runState, runConfig, progress, schemaVersion: CHECKPOINT_SCHEMA_VERSION }
}

function toInitResultShape(ctx: LoopContext): HarnessInitResult {
  return {
    worldModel: ctx.worldModel,
    callerState: ctx.callerState,
    controlState: ctx.controlState,
    taskGraph: ctx.taskGraph,
    diagnostics: ctx.diagnostics,
    hypothesisSet: ctx.hypothesisSet,
    evidenceStore: ctx.evidenceStore,
    memoryState: ctx.memoryState,
    strategyState: ctx.strategyState,
    failureDiagnostics: ctx.failureDiagnostics,
    outputContract: ctx.outputContract,
    beliefDepGraph: ctx.beliefDepGraph,
    depGraphBudget: ctx.depGraphBudget,
    maxSteps: ctx.maxSteps,
    decompositionGate: ctx.controlState.permission !== 'DENY',
    valid: true,
    errors: [],
    processConceptId: ctx.processConceptId,
  }
}

/** AL8b: iteration-boundary policy re-evaluation (after each updateDiagnostics). Never throws (AL-4). */
function reevaluatePolicy(ctx: LoopContext): void {
  if (!ctx.reevaluateLayerPolicy) return
  try {
    const next = ctx.reevaluateLayerPolicy({ iteration: ctx.stepsUsed, diagnostics: ctx.diagnostics, failures: ctx.failureDiagnostics.failure_history.length })
    if (next) ctx.layerPolicy = next
  } catch { /* keep the previous policy */ }
}

/** Runs a host observability callback; a throwing handler (e.g. a tracing hook) must never break the run. */
function notifyHost(fn: () => void): void {
  try {
    fn()
  } catch {
    /* an observability handler must never break the run */
  }
}

function reportLayer(ctx: LoopContext, layer: LayerActivityEvent['layer'], fired: boolean, reason: string, gate?: GateOutcome): void {
  // AL8b: decision/trigger ride along only when the policy (not the static baseline) decided.
  notifyHost(() => ctx.onLayerActivity?.(gate?.trigger !== undefined ? { layer, fired, reason, decision: gate.decision, trigger: gate.trigger } : { layer, fired, reason }))
}

/**
 * F3 (the internal plan) — a turn that strands (a FAILED task, nothing
 * left runnable, nothing ever completed) must not return an empty `finalResult`: the caller
 * (personal-assistant's response-service.ts) turns a non-string `finalResult` into the draft
 * reply, and for the one-loop proposer path there is no draft — so `''` reaches the user as a
 * silent no-op. This gives them an explicit, honest "couldn't complete" line instead. Only used
 * when `ctx.finalResult` is not already a usable string.
 */
/** Opens the stranded-turn reply naming a step the completion check rejected; hosts test for it to avoid repeating that news. */
export const NOT_ACCOMPLISHED_REPLY_PREFIX = "I didn't complete this step — "

function stalledTurnFallbackResult(ctx: LoopContext): string {
  // The completion check judged a task's output did not do the task: say which and why, rather than a
  // generic "ran into a problem" — that reason is what the user needs to steer the next step.
  if (ctx.lastNotAccomplished) {
    const { taskDescription, reason } = ctx.lastNotAccomplished
    return `${NOT_ACCOMPLISHED_REPLY_PREFIX}${taskDescription.slice(0, 200)}: ${reason.slice(0, 300)} Nothing after it has run. Tell me how you'd like to proceed, or rephrase what you need.`
  }
  const lastFailure = ctx.failureDiagnostics.failure_history.at(-1)?.description ?? ''
  const detail = lastFailure.replace(/^Task failed:\s*/i, '').trim()
  return detail
    ? `I couldn't complete this — I kept running into a problem (${detail.slice(0, 200)}). You may want to retry or rephrase what you need.`
    : `I couldn't complete this — I kept running into a problem and stopped before finishing. You may want to retry or rephrase what you need.`
}

/** True once any belief/coverage/verification sub-dimension has crossed CAUTION_THRESHOLD (0.4) — mirrors resolveControlState's own Tier 3 read of these fields. */
function anyDiagnosticSubDimensionCautious(diagnostics: LoopContext['diagnostics']): boolean {
  const healthy = [
    diagnostics.belief_health.freshness, diagnostics.belief_health.consistency, diagnostics.belief_health.support,
    diagnostics.coverage_health.symptom_coverage, diagnostics.coverage_health.explanation_coverage,
    diagnostics.verification_health.strength, diagnostics.verification_health.feasibility,
    diagnostics.execution_health.progress_rate,
  ]
  const inverted = [diagnostics.execution_health.failure_recurrence, diagnostics.execution_health.oscillation_score]
  return healthy.some(v => v < CAUTION_THRESHOLD) || inverted.some(v => v > 1 - CAUTION_THRESHOLD)
}

/**
 * Eval-only ablation (control_state): what `skipControlState` substitutes for the resolver — a
 * default ALLOW/NORMAL state stamped with the WorldModel's current generation_id, so the staleness
 * check in `_maybeResolve` stays satisfied without any tier ever firing.
 */
function pinnedNormalControlState(worldModel: WorldModel): ControlState {
  const cs = new ControlState()
  cs.generation_id = worldModel.generation_id
  return cs
}

/** The resolver the action/post-exec gates and parallel reconcile re-resolve with when stale. */
function controlStateResolverFor(ctx: LoopContext): ControlStateResolverFn {
  return ctx.skipControlState ? (_diagnostics, worldModel) => pinnedNormalControlState(worldModel) : resolveControlState
}

const SEMANTIC_SOURCE = 'semantic'

function hasSemanticHypotheses(ctx: LoopContext): boolean {
  return ctx.hypothesisSet.active.some((h) => h.generation_sources.includes(SEMANTIC_SOURCE))
}

function emitSemanticHypothesis(ctx: LoopContext, event: SemanticHypothesisEvent): void {
  try {
    ctx.onSemanticHypothesis?.(event)
  } catch {
    /* an observability handler must never break the run */
  }
}

/**
 * Asks the host, once per run, for competing explanations of an underdetermined request and adds them to the active set.
 * Fails open: a missing hook, a null/empty answer or a throw changes nothing.
 */
async function generateSemanticHypotheses(ctx: LoopContext): Promise<void> {
  if (!ctx.semanticHypotheses || hasSemanticHypotheses(ctx) || ctx.semanticHypothesesAsked) return
  ctx.semanticHypothesesAsked = true
  let proposals: SemanticHypothesisProposal[] | null = null
  try {
    proposals = await ctx.semanticHypotheses({
      objective: ctx.objective,
      observations: ctx.evidenceStore.observations.map((o) => o.obs),
      beliefs: ctx.worldModel.beliefs.map((b) => b.statement),
    })
  } catch {
    return
  }
  const usable = (proposals ?? []).filter((p) => typeof p?.explanation === 'string' && p.explanation.trim() !== '')
  if (usable.length === 0) return
  const created = usable.map((p, i) => ({
    id: `sem_${[...ctx.hypothesisSet.active, ...ctx.hypothesisSet.eliminated].filter((h) => h.generation_sources.includes(SEMANTIC_SOURCE)).length + i}`,
    explanation: p.explanation.trim(),
    confidence: typeof p.confidence === 'number' && p.confidence >= 0 && p.confidence <= 1 ? p.confidence : 1 / usable.length,
    predicted_observations: (p.predicted_observations ?? []).filter((x) => typeof x === 'string' && x.trim() !== ''),
    discriminating_evidence: [] as string[],
    generation_sources: [SEMANTIC_SOURCE],
    diversity_score: 0,
    ...(typeof p.separating_check === 'string' && p.separating_check.trim() ? { separating_check: p.separating_check.trim() } : {}),
  }))
  ctx.hypothesisSet.active.push(...created)
  emitSemanticHypothesis(ctx, {
    kind: 'generated',
    hypotheses: created.map((h) => ({ id: h.id, explanation: h.explanation, predicted_observations: h.predicted_observations, ...(h.separating_check ? { separating_check: h.separating_check } : {}) })),
  })
}

/**
 * After an execution's evidence is recorded: ask the host which semantic hypotheses the new observations contradict and
 * eliminate them. Fails open (no hook, nothing new, null, throw ⇒ nothing is eliminated).
 */
async function judgeSemanticHypotheses(ctx: LoopContext): Promise<void> {
  if (!ctx.semanticHypothesisJudge || !hasSemanticHypotheses(ctx)) return
  const observations = ctx.evidenceStore.observations
  const from = ctx.lastJudgedObservationCount ?? 0
  const fresh = observations.slice(from)
  ctx.lastJudgedObservationCount = observations.length
  if (fresh.length === 0) return
  const live = ctx.hypothesisSet.active.filter((h) => h.generation_sources.includes(SEMANTIC_SOURCE))
  let verdict: { contradicted: Array<{ id: string; reason?: string }> } | null = null
  try {
    verdict = await ctx.semanticHypothesisJudge({
      hypotheses: live.map((h) => ({ id: h.id, explanation: h.explanation, predicted_observations: h.predicted_observations })),
      observations: fresh.map((o) => o.obs),
    })
  } catch {
    return
  }
  for (const c of verdict?.contradicted ?? []) {
    const h = live.find((x) => x.id === c?.id)
    if (!h) continue
    ctx.hypothesisSet.eliminate(h)
    emitSemanticHypothesis(ctx, { kind: 'eliminated', id: h.id, explanation: h.explanation, ...(c.reason ? { reason: c.reason } : {}) })
  }
}

/**
 * Returns the id of the task to reopen when the host's `reviewerRevision` turns the pass's verdict into a note; otherwise
 * undefined. Only at the end of a run (every task COMPLETE), only when the pass reopened nothing itself, and
 * only once.
 */
function maybeReopenForReviewerRevision(ctx: LoopContext, result: { pending_verdict: ReviewerVerdict | null; reopened_task_ids: string[] }): string | undefined {
  if (!ctx.reviewerRevision || ctx.reviewerRevisionDone || !result.pending_verdict || result.reopened_task_ids.length > 0) return undefined
  if (!ctx.taskGraph.tasks.every((t) => t.status === 'COMPLETE')) return undefined
  const taskId = ctx.lastCompletedTaskId
  if (!taskId || !ctx.taskGraph.getTask(taskId)) return undefined
  let note: string | null = null
  try {
    note = ctx.reviewerRevision(result.pending_verdict)
  } catch {
    return undefined
  }
  if (!note || !note.trim()) return undefined
  ctx.reviewerRevisionDone = true
  try {
    ctx.onReviewerRevision?.({ taskId, note })
  } catch {
    /* an observability handler must never break the run */
  }
  return taskId
}

/** The constraints the host's judge says the final reply violates; empty when there is no judge, no constraint, no reply, or the judge fails (a failing check never fails a reply that would have passed). */
/**
 * `retryFailedSystemErrors`: true for the FIRST system-error failure of a task (the executor threw / reported a failure
 * without a kind), false for any later one or any other kind of failure. Marks the task as retried.
 */
function retrySystemErrorOnce(ctx: LoopContext, taskId: string, execResult: { success: boolean; failure_kind?: string }): boolean {
  if (ctx.retryFailedSystemErrors !== true || execResult.success || execResult.failure_kind !== 'system_error') return false
  const retried = (ctx.systemErrorRetried ??= new Set<string>())
  if (retried.has(taskId)) return false
  retried.add(taskId)
  return true
}

async function judgeConstraints(ctx: LoopContext, judge: SemanticConstraintJudge | undefined): Promise<Array<{ constraint: string; reason?: string }>> {
  if (!judge || ctx.callerState.current_constraints.length === 0) return []
  const reply = typeof ctx.finalResult === 'string' ? ctx.finalResult : ctx.finalResult == null ? '' : JSON.stringify(ctx.finalResult)
  if (reply.trim() === '') return []
  // The could-not-complete reply is the harness's own notice, not an answer: judging it against the user's constraints
  // ("two sentences", "friendly tone") would throw a graceful failure message into a failed turn.
  if (reply === ctx.stalledFallbackText) return []
  try {
    return (await judge({ constraints: [...ctx.callerState.current_constraints], reply })).violated ?? []
  } catch {
    return []
  }
}

/**
 * Returns the id of the task to reopen when the host opted into `onConstraintRevision`: only once per run, only at the end
 * of a run (every task COMPLETE). Fires the handler with the note the proposer should see.
 */
function maybeReopenForConstraintRevision(ctx: LoopContext, violated: Array<{ constraint: string; reason?: string }>): string | undefined {
  if (!ctx.onConstraintRevision || ctx.constraintRevisionDone) return undefined
  if (!ctx.taskGraph.tasks.every((t) => t.status === 'COMPLETE')) return undefined
  const taskId = ctx.lastCompletedTaskId
  if (!taskId || !ctx.taskGraph.getTask(taskId)) return undefined
  ctx.constraintRevisionDone = true
  const note = violated.map(v => `Your answer violates the constraint "${v.constraint}"${v.reason ? ` (${v.reason})` : ''}.`).join(' ')
  try {
    ctx.onConstraintRevision({ taskId, note, violated })
  } catch {
    /* an observability handler must never break the run */
  }
  return taskId
}

/**
 * Reports the `diagnostics` layer. `onlyOnChange` (the post-execution pass) reports nothing unless the
 * verdict differs from what this run last reported, so a quiet iteration adds no second line.
 */
function reportDiagnosticsHealth(ctx: LoopContext, onlyOnChange = false): void {
  const cautious = anyDiagnosticSubDimensionCautious(ctx.diagnostics)
  if (onlyOnChange && ctx.lastReportedDiagnosticsCautious === cautious) return
  ctx.lastReportedDiagnosticsCautious = cautious
  reportLayer(ctx, 'diagnostics', true, cautious ? 'a sub-dimension crossed the caution threshold' : 'Health: nominal')
}

function resolveAndStamp(ctx: LoopContext): void {
  // Phase I / INV-18: one-shot — whatever pendingReviewerVerdict is currently set (if
  // any) is consumed by this one resolve call and cleared immediately after, so a stale
  // finding does not pin CAUTIOUS forever and the *next* resolveAndStamp call (wherever
  // it occurs) sees nothing pending.
  const verdict = ctx.pendingReviewerVerdict
  ctx.pendingReviewerVerdict = undefined
  const newCS = ctx.skipControlState
    ? pinnedNormalControlState(ctx.worldModel)
    : resolveControlState(ctx.diagnostics, ctx.worldModel, ctx.failureDiagnostics, undefined, verdict)
  ctx.controlState.generation_id = newCS.generation_id
  ctx.controlState.permission = newCS.permission
  ctx.controlState.execution_mode = newCS.execution_mode
  ctx.controlState.escalation = newCS.escalation
  ctx.controlState.risk_estimate = newCS.risk_estimate
  ctx.controlState.confidence_estimate = newCS.confidence_estimate
  ctx.controlState.escalation_reason = newCS.escalation_reason
  ctx.controlState.block_mask = [...newCS.block_mask]
  ctx.controlState.notes = [...newCS.notes]
}

/**
 * One full pass of the harness main loop, expressed as an async generator so a
 * caller can suspend between iterations. Yields a checkpoint after every
 * iteration that reaches the bottom of the loop body (an iteration that takes
 * an early `continue` — e.g. RESTART_ITERATION — made no task progress, so it
 * isn't checkpointed; the next iteration through this same point will be).
 * Returns normally when the loop exits via `break` (all tasks complete, or no
 * task available). EscalationHalt still propagates as a thrown/rejected error.
 */
async function* driveMainLoop(ctx: LoopContext): AsyncGenerator<HarnessCheckpoint, void, void> {
  while (true) {
    let currentTask: Task
    let concurrentTask: Task | null = null
    let gateResult: 'PASS' | 'BLOCK' | 'ESCALATE'
    let shouldGatherEvidence = false
    const sig = ctx.complexitySignal

    if (ctx.pendingProposal) {
      // Resuming exactly where a prior process paused, mid-iteration, at the new
      // propose→gate suspend point below (the yield right after action_gate) — re-derive the
      // same task/decision instead of re-running select_task/estimate_risk/review (which
      // already ran once, before the pause; re-running them would double-count stepsUsed and
      // risk a second, redundant estimateVOI mutation to diagnostics). No concurrent-task
      // parallel branch is resumed this way (deliberate scope reduction, flagged in the plan):
      // a real process restart loses the opportunistic parallel candidate select_task found —
      // the resumed task simply executes serially instead.
      const p = ctx.pendingProposal
      ctx.pendingProposal = undefined
      const resumed = ctx.taskGraph.tasks.find(t => t.id === p.taskId)
      if (!resumed) continue // stale proposal for a task that no longer exists — replan fresh next iteration
      currentTask = resumed
      gateResult = p.gateResult
      shouldGatherEvidence = p.shouldGatherEvidence
      // INV-15: replaying a stored gate decision is still a gate decision covering the execute()
      // call that follows — recorded so a scan of nodeExecutionOrder can verify the invariant
      // without needing to know about pendingProposal at all (same as a fresh 'action_gate').
      ctx.nodeExecutionOrder.push(p.kind === 'continuation' ? 'action_gate_replay_continuation' : 'action_gate_replay')
      if (p.kind === 'continuation') {
        // Unlike a 'proposal' resume (which just finishes an iteration whose stepsUsed
        // increment already happened before the original suspend — see the else branch below),
        // a 'continuation' resume falls through to a brand-new execute() call further down: it's
        // a genuine new unit of work, not a replay. Without counting it here, a toolFn that keeps
        // reporting 'continue' forever never reaches the maxSteps backstop below and spins forever.
        ctx.stepsUsed++
        if (ctx.stepsUsed > ctx.maxSteps) {
          const exhaust = escalateBudgetExhausted(ctx.stepsUsed, ctx.maxSteps)
          // Flag-OFF byte-identical (Protected Invariants): resolve the effective mode
          // HERE — this site had no question/options before Q7, so askQuestion()'s own
          // internal degrade (still-populated collapsed question/options) isn't good
          // enough; off must fall through to the exact pre-Q7 plain EscalationHalt.
          if (resolveAskMode({ globalEnabled: ctx.askMode === 'enabled' })) {
            askQuestion([buildBudgetExhaustedQuestion(ctx.stepsUsed)], {
              reason: 'budget_exhausted',
              missingInfo: exhaust.missing_info,
              currentTaskSummary: `Exhausted at step ${ctx.stepsUsed} (no iteration reached completion)`,
              globalEnabled: ctx.askMode === 'enabled',
            })
          }
          throw new EscalationHalt({
            reason: 'budget_exhausted',
            missing_info: exhaust.missing_info,
            current_task_summary: `Exhausted at step ${ctx.stepsUsed} (no iteration reached completion)`,
            escalated_at: new Date().toISOString(),
          })
        }
      }
    } else {
    ctx.stepsUsed++
    // Backstop budget check: the "normal path" exhaustion check further down (stepsUsed >=
    // maxSteps) only runs once an iteration reaches the bottom of the loop body, but several
    // branches above `continue` before ever reaching it (action_gate BLOCKED with nothing to
    // recover from, e.g. a low progress_rate on a large task graph with cannotMakeProgress's
    // own history-based stall detection not yet primed — a real, previously-latent deadlock
    // this exposed). Without this, such a branch spins forever instead of ever escalating.
    if (ctx.stepsUsed > ctx.maxSteps && !nothingLeftToRun(ctx)) {
      const exhaust = escalateBudgetExhausted(ctx.stepsUsed, ctx.maxSteps)
      if (resolveAskMode({ globalEnabled: ctx.askMode === 'enabled' })) {
        askQuestion([buildBudgetExhaustedQuestion(ctx.stepsUsed)], {
          reason: 'budget_exhausted',
          missingInfo: exhaust.missing_info,
          currentTaskSummary: `Exhausted at step ${ctx.stepsUsed} (no iteration reached completion)`,
          globalEnabled: ctx.askMode === 'enabled',
        })
      }
      throw new EscalationHalt({
        reason: 'budget_exhausted',
        missing_info: exhaust.missing_info,
        current_task_summary: `Exhausted at step ${ctx.stepsUsed} (no iteration reached completion)`,
        escalated_at: new Date().toISOString(),
      })
    }
    ctx.nodeExecutionOrder.push('context_compression')
    if (ctx.tokenBudget) {
      let used = 0
      try { used = Math.floor(ctx.tokenBudget.used()) } catch { /* a failing host reader leaves the pressure at 0 */ }
      ctx.memoryState.token_budget = { total: Math.max(1, Math.floor(ctx.tokenBudget.total)), used: Number.isFinite(used) && used > 0 ? used : 0 }
    }

    contextCompression(
      ctx.memoryState, ctx.worldModel, ctx.beliefDepGraph, ctx.depGraphBudget,
      ctx.hypothesisSet, ctx.taskGraph, ctx.diagnostics, ctx.controlState, ctx.callerState,
    )

    ctx.nodeExecutionOrder.push('check_caller_updates')
    const updateResult = await pollCallerUpdates(ctx)
    if (updateResult === RESTART_ITERATION) {
      resolveAndStamp(ctx)
      continue
    }

    // ─── SUB-STEP A ───────────────────────────────────────────────────────

    ctx.nodeExecutionOrder.push('detect_contradictions')
    const contradictionsBefore = ctx.worldModel.contradictions.length
    // Fires automatically once >=2 beliefs exist — detectContradictions is already cheap
    // with fewer, so no separate gate is needed; Phase 1's belief-writing fix is what makes
    // this stop being permanently a no-op (Phase 2, layer 4).
    detectContradictions(ctx.worldModel, ctx.evidenceStore, ctx.hypothesisSet, undefined, ctx.beliefDepGraph)

    // Semantic check, layered on top of the lexical one above — one call for whatever's new
    // since the last check (never per-pair, never a full re-scan: old-vs-old was already
    // cleared by a previous call and never changes). Only actually reaches an LLM when the
    // caller's contradictionChecker decides the delta warrants it (e.g. it isn't all
    // coding/system-state facts the lexical check already handles — see personal-assistant's
    // looksLikeCodingFact).
    if (ctx.contradictionChecker && hookOn(ctx, 'semantic_contradiction')) {
      let skipCoverageMark = false
      const newBeliefs = ctx.worldModel.beliefs.slice(ctx.lastContradictionCheckCount)
      const existingBeliefs = ctx.worldModel.beliefs.slice(0, ctx.lastContradictionCheckCount)
      if (newBeliefs.length > 0 && (existingBeliefs.length > 0 || newBeliefs.length >= 2)) {
        // Fails open like the other semantic hooks: a throwing checker (LLM/network error) leaves the
        // lexical result as is, and its beliefs stay uncovered so a later iteration asks again.
        let found: ExternalContradictionInput[] | null = null
        try {
          found = await ctx.contradictionChecker(
            newBeliefs.map(b => ({ id: b.id, statement: b.statement })),
            existingBeliefs.map(b => ({ id: b.id, statement: b.statement })),
          )
        } catch {
          found = null
        }
        if (found === null) skipCoverageMark = true
        for (const input of found ?? []) {
          recordExternalContradiction(ctx.worldModel, input, ctx.beliefDepGraph)
        }
      }
      // Marks these beliefs covered regardless of whether the checker actually called an LLM
      // — a "these are coding facts, skip" decision is still a completed check, courtesy of
      // the always-on lexical pass above.
      if (!skipCoverageMark) ctx.lastContradictionCheckCount = ctx.worldModel.beliefs.length
    }

    if (ctx.worldModel.contradictions.length > contradictionsBefore) {
      reportLayer(ctx, 'contradiction', true, `Heads up — this seems to conflict with something you told me earlier: ${ctx.worldModel.contradictions.at(-1)?.description ?? ''}`)
    } else {
      reportLayer(ctx, 'contradiction', false, ctx.worldModel.beliefs.length >= 2 ? 'checked — no conflicts found' : 'fewer than 2 beliefs — nothing to compare')
    }

    const hypothesisGate = resolveGate(ctx.layerPolicy, 'hypothesis_display',
      (sig?.taskCount ?? 1) > 1 || (sig?.riskLevel ?? 'LOW') !== 'LOW' || ctx.failureDiagnostics.failure_history.length > 0)
    const hypothesisNotable = hypothesisGate.on
    ctx.nodeExecutionOrder.push('generate_update_hypotheses')
    // Always computed (never skipped) — diagnostics.coverage_health.explanation_coverage is
    // derived from hypothesisSet's entropy (computeSourceEntropy), which resolveControlState
    // reads for its BLOCKED/CAUTIOUS tiers; eliding this call for a "quiet" turn starves that
    // signal and can wedge the whole run in BLOCKED. What's actually gated per Phase 2, layer 3
    // is only whether this is worth surfacing to the user, not whether the computation runs.
    generateUpdateHypotheses(ctx.worldModel, ctx.evidenceStore, ctx.hypothesisSet, ctx.failureDiagnostics, ctx.memoryState)
    await generateSemanticHypotheses(ctx)
    const semanticActive = ctx.hypothesisSet.active.filter((h) => h.generation_sources.includes(SEMANTIC_SOURCE)).length
    if (semanticActive > 0) {
      reportLayer(ctx, 'hypothesis', true, `Weighing ${semanticActive} competing explanation${semanticActive === 1 ? '' : 's'} for this request`, hypothesisGate)
    } else {
      reportLayer(ctx, 'hypothesis', hypothesisNotable && ctx.hypothesisSet.active.length > 1,
        hypothesisNotable && ctx.hypothesisSet.active.length > 1
          ? `Considered ${ctx.hypothesisSet.active.length} ways this request could be understood; going with the most direct one`
          : 'single clear LOW-risk task — no competing explanation worth surfacing', hypothesisGate)
    }

    ctx.nodeExecutionOrder.push('update_diagnostics')
    updateDiagnostics(ctx.worldModel, ctx.hypothesisSet, ctx.taskGraph, ctx.failureDiagnostics, ctx.beliefDepGraph, ctx.diagnostics)
    reevaluatePolicy(ctx)
    reportDiagnosticsHealth(ctx)

    ctx.worldModel.incrementGenerationId()
    ctx.nodeExecutionOrder.push('resolve_control_state')
    resolveAndStamp(ctx)
    reportLayer(ctx, 'control_state', riskSummary(ctx.controlState) !== 'NORMAL', ctx.controlState.permission === 'DENY'
      ? `Pausing — ${ctx.controlState.escalation_reason ?? 'blocked'}`
      : ctx.controlState.execution_mode === 'CAUTIOUS'
        ? `Proceeding carefully — ${ctx.controlState.escalation_reason ?? 'elevated risk'}`
        : 'NORMAL')

    const allComplete = ctx.taskGraph.tasks.length > 0 &&
      ctx.taskGraph.tasks.every(t => t.status === 'COMPLETE')
    if (allComplete) return

    ctx.nodeExecutionOrder.push('update_task_graph')
    updateTaskGraph(ctx.objective, ctx.worldModel, ctx.hypothesisSet, ctx.taskGraph)

    ctx.nodeExecutionOrder.push('select_task')
    const selectResult = selectTask(ctx.taskGraph, ctx.controlState)

    if (selectResult.escalate) {
      throw new EscalationHalt({
        reason: 'cannot_make_progress',
        missing_info: ['HUMAN_REQUIRED escalation from select_task'],
        current_task_summary: 'task selection triggered escalation',
        escalated_at: new Date().toISOString(),
      })
    }

    if (selectResult.task === null) {
      // F3 — the graph has no runnable task. If nothing ever completed and something FAILED, the
      // turn stalled: end with an explicit could-not-complete reply rather than an empty one. A
      // clean finish (a string `finalResult`, or a graph that simply had nothing to do) is
      // untouched.
      const noUsableResult = typeof ctx.finalResult !== 'string' || ctx.finalResult.trim() === ''
      if (noUsableResult && ctx.taskGraph.tasks.some(t => t.status === 'FAILED')) {
        const fallback = stalledTurnFallbackResult(ctx)
        ctx.finalResult = fallback
        ctx.stalledFallbackText = typeof fallback === 'string' ? fallback : undefined
        reportLayer(ctx, 'recovery', true, 'turn stalled with no answer — returning an explicit could-not-complete reply')
      }
      return
    }

    currentTask = selectResult.task
    concurrentTask = selectResult.concurrentTask
    applyTaskOutcome(ctx.taskGraph, currentTask.id, { status: 'RUNNING' })

    ctx.nodeExecutionOrder.push('estimate_risk')
    // module_type reflects what this turn actually does (Phase 2, layer 8) instead of a
    // constant 'business_logic' placeholder — a HIGH-risk turn (a write/send/delete-shaped
    // request) is treated as infrastructure-grade risk; everything else composites normally.
    const riskAction: RiskableAction = {
      module_type: ctx.complexitySignal?.riskLevel === 'HIGH' ? 'infrastructure' : 'business_logic',
      metadata: {},
    }
    estimateRisk(riskAction, ctx.taskGraph, ctx.worldModel)
    reportLayer(ctx, 'execution', true, `module_type=${riskAction.module_type}`)

    ctx.nodeExecutionOrder.push('estimate_voi')
    const voiResult = estimateVOI(ctx.diagnostics, ctx.worldModel, ctx.hypothesisSet, ctx.evidenceStore.tool_availability_manifest)
    shouldGatherEvidence = voiResult.should_gather_evidence

    ctx.nodeExecutionOrder.push('review_proposed_change')
    let reviewResult = reviewProposedChange(
      { description: currentTask.description },
      currentTask,
      ctx.worldModel,
      ctx.outputContract,
      ctx.hypothesisSet,
      ctx.evidenceStore,
      ctx.consecutiveReviewFailures,
    )

    // Semantic escalation layered on top of the lexical isNegation check above — only when
    // the lexical checks already passed (a lexical failure is already the strongest signal
    // available; no need to also ask an LLM), and only when there's a HIGH-confidence belief
    // or hypothesis prediction to actually check the change against. Never called per
    // candidate pair — one call reviewing the change against everything relevant at once.
    if (reviewResult.passed && ctx.semanticChangeReviewer && hookOn(ctx, 'change_review')) {
      const highConfidenceBeliefs = ctx.worldModel.beliefs
        .filter(b => b.confidence >= 0.8)
        .map(b => ({ id: b.id, statement: b.statement }))
      // Caller-trusted facts (see changeReviewFacts) — same shape, deduped against the beliefs above.
      const known = new Set(highConfidenceBeliefs.map(b => b.statement))
      ;(ctx.changeReviewFacts?.() ?? []).forEach((f, i) => {
        if (known.has(f.statement)) return
        known.add(f.statement)
        highConfidenceBeliefs.push({ id: `known-fact-${i}`, statement: f.statement })
      })
      const hypothesisPredictions = ctx.hypothesisSet.active.flatMap(h => h.predicted_observations)
      if (highConfidenceBeliefs.length > 0 || hypothesisPredictions.length > 0) {
        let semanticResult: { conflict: boolean; reason?: string } = { conflict: false }
        try {
          semanticResult = await ctx.semanticChangeReviewer({
            changeDescription: currentTask.description,
            highConfidenceBeliefs,
            hypothesisPredictions,
          })
        } catch {
          /* fails open: a throwing reviewer means no conflict was found */
        }
        if (semanticResult?.conflict) {
          // Advisory, not a gate: failing the review here would re-run the identical task against
          // the identical beliefs (same verdict every time) until the step budget ran out — and
          // would throw away a draft that may already address the conflict. The host decides how
          // to surface the reason instead (see onReviewConflict).
          notifyHost(() => ctx.onReviewConflict?.({
            taskId: currentTask.id,
            reason: semanticResult.reason ?? 'Semantic review found a conflict with known context',
          }))
        }
      }
    }

    if (!reviewResult.passed) {
      applyTaskOutcome(ctx.taskGraph, currentTask.id, { status: 'PENDING', fromExecutionLayer: false })
      if (reviewResult.escalation_triggered) {
        // Q7: offer the diagnosed candidate fixes as a structured question when there's
        // more than one plausible one (see diagnoseReviewFailureOptions' twin note — in
        // practice reviewProposedChange's short-circuit means this is almost always
        // undefined here, and the plain halt below fires exactly as it did pre-Q7).
        // Flag-OFF byte-identical (Protected Invariants): this site had no question/
        // options at all before Q7, so the effective mode is resolved HERE rather than
        // relying on askQuestion()'s own internal degrade, which would still populate a
        // collapsed single question/options pair even while nominally "off".
        const fixOptions = resolveAskMode({ globalEnabled: ctx.askMode === 'enabled' })
          ? diagnoseReviewFailureOptions(reviewResult.failed_dimensions)
          : undefined
        if (fixOptions) {
          askQuestion([buildReviewFailureQuestion(fixOptions)], {
            reason: 'review_failure',
            missingInfo: reviewResult.failed_dimensions.map(d => d.reason),
            currentTaskSummary: currentTask.description,
            globalEnabled: ctx.askMode === 'enabled',
          })
        }
        throw new EscalationHalt({
          reason: 'review_failure',
          missing_info: reviewResult.failed_dimensions.map(d => d.reason),
          current_task_summary: currentTask.description,
          escalated_at: new Date().toISOString(),
        })
      }
      continue
    }

    ctx.nodeExecutionOrder.push('action_gate')
    gateResult = actionGate(
      { required_resources: [] },
      ctx.controlState,
      ctx.worldModel,
      ctx.diagnostics,
      ctx.failureDiagnostics,
      controlStateResolverFor(ctx),
    )

    // ─── NEW SUSPEND POINT ──────────────────────────────────────────────
    // The first real pause point between an action proposal and its execution — previously
    // the only yield was after execute() had already run (post-hoc replay, not a decision
    // point). Persisted into ctx.pendingProposal (part of the checkpoint toCheckpoint below
    // produces) before yielding, so a real process restart between this yield and the
    // caller's resume can still recover exactly this pause via the `if (ctx.pendingProposal)`
    // branch above — not just an in-memory generator suspension. Only the fresh path yields
    // here; the resumed path (above) already carries a decision the caller has seen and
    // asked to resume past, so it falls straight through to the shared BLOCK/ESCALATE-or-
    // execute handling below instead of re-announcing the same proposal.
    ctx.pendingProposal = { taskId: currentTask.id, gateResult, shouldGatherEvidence, kind: 'proposal' }
    yield toCheckpoint(ctx)
    ctx.pendingProposal = undefined
    }

    if (gateResult === 'ESCALATE' || gateResult === 'BLOCK') {
      applyTaskOutcome(ctx.taskGraph, currentTask.id, { status: 'PENDING', fromExecutionLayer: false })
      const stalled = cannotMakeProgress(ctx.strategyState, ctx.failureDiagnostics)
      notifyHost(() => ctx.onGateDecision?.({
        taskId: currentTask.id,
        result: gateResult,
        reason: ctx.controlState.escalation_reason,
        haltedRun: stalled,
      }))
      if (stalled) {
        throw new EscalationHalt({
          reason: 'cannot_make_progress',
          missing_info: [ctx.strategyState.stall_reason ?? 'unknown'],
          current_task_summary: currentTask.description,
          escalated_at: new Date().toISOString(),
        })
      }
      continue
    }

    ctx.nodeExecutionOrder.push('execute')
    const proposedChange: ProposedExecutionChange = {
      description: currentTask.description,
      change_type: 'file_mutation',
    }
    const toolFn = ctx.toolExecutors[currentTask.id] ?? ctx.toolExecutors['default'] ?? (() => ({ completed: true }))
    const execResult = await execute(proposedChange, toolFn, {
      worldModel: ctx.worldModel,
      evidenceStore: ctx.evidenceStore,
      taskGraph: ctx.taskGraph,
      currentTask,
      memoryState: ctx.memoryState,
      beliefDepGraph: ctx.beliefDepGraph,
      controlState: ctx.controlState,
      diagnostics: ctx.diagnostics,
      failureDiagnostics: ctx.failureDiagnostics,
    })

    // Phase D1: toolFn reported "more work to do" via a ContinuableExecutionOutcome — the task
    // stays RUNNING (never touched above; applyTaskOutcome only set it RUNNING once, on
    // selection) and this attempt's approval is re-used via the exact same pendingProposal
    // suspend point Phase 3 built, rather than re-running select_task/estimate_risk/review for
    // a task that's already mid-flight. A real process restart between two 'continue' steps
    // resumes correctly because pendingProposal is part of the checkpoint. Deliberately skips
    // the concurrent-task dispatch below and the verify/postExecGate/update_task_state block —
    // none of those apply until the task actually finishes (status 'complete' or 'failed').
    if (execResult.status === 'continue') {
      // Deliberately left set across the `continue` below (unlike the fresh-proposal suspend
      // point above, which falls through in the same iteration) — the next while(true) pass's
      // `if (ctx.pendingProposal)` branch at the top of the loop is what actually resumes this
      // same task, exactly as it would after a real process restart via buildResumedContext.
      ctx.pendingProposal = { taskId: currentTask.id, gateResult, shouldGatherEvidence, kind: 'continuation' }
      yield toCheckpoint(ctx)
      continue
    }

    // The executor returning is not the same as the task being done: ask the host whether the output
    // accomplished it. Not done ⇒ the task takes the failure branch below, exactly as a failed executor
    // would, and no "Completed:" belief is written for it.
    let taskAccomplished = true
    if (execResult.success && ctx.semanticTaskCompletion) {
      let verdict: { done: boolean; reason?: string } = { done: true }
      try {
        verdict = await ctx.semanticTaskCompletion({ taskDescription: currentTask.description, output: execResult.output })
      } catch {
        /* a failing check must never block a task the executor completed */
      }
      if (!verdict.done) {
        taskAccomplished = false
        const why = verdict.reason ?? 'the output did not do what the task asked'
        ctx.lastNotAccomplished = { taskDescription: currentTask.description, reason: why }
        // Mirror execute()'s own failure bookkeeping (nodes/execute.ts recordFailure), minus the
        // SYSTEM_ERROR evidence item — the tool worked, so tool reliability must not be dinged.
        ctx.worldModel.observations.push({
          id: `not-done-${currentTask.id}-${ctx.stepsUsed}`,
          content: `TASK_NOT_ACCOMPLISHED: ${why}`,
          source: 'task_completion_check',
          recorded_at: new Date().toISOString(),
        })
        try {
          applyTaskOutcome(ctx.taskGraph, currentTask.id, { status: 'FAILED', fromExecutionLayer: true })
        } catch {
          /* task may already be in another state */
        }
        try {
          ctx.onTaskNotAccomplished?.({ taskId: currentTask.id, reason: why })
        } catch {
          /* an observability handler must never break the run */
        }
        reportLayer(ctx, 'verification', true, `task not accomplished — ${why}`)
      }
    }

    // Phase 2, layer 7 (plan sub-item 2.7): dispatch select_task's concurrentTask instead of
    // silently dropping it — real only for a non-HIGH-risk pair (select_task.ts's own
    // hasOverlap/conflict-probability check already guarantees disjoint write domains; never
    // a write_file/run_shell_command pair — those keep serial execution + human approval). The
    // two tasks execute against independently-forked WorldModel branches (this task's
    // ctx.worldModel, and a clone for the concurrent one), reconciled via the already-
    // implemented reconcileParallelBranches/mergeWorldModels right before this iteration's
    // checkpoint. evidenceStore/taskGraph/diagnostics/hypothesisSet stay shared across both
    // branches (reconcileParallelBranches' own design) — only WorldModel forks.
    const parallelEligible = concurrentTask !== null && currentTask.risk_level !== 'HIGH' && concurrentTask.risk_level !== 'HIGH'
    reportLayer(ctx, 'planning', parallelEligible, parallelEligible && concurrentTask
      ? `Reading "${currentTask.description}" and "${concurrentTask.description}" at once`
      : concurrentTask ? 'candidate found but too risky to run in parallel — serial execution' : 'one eligible task — serial execution')

    let branchWorldModel: WorldModel | null = null
    let branchExecSucceeded = false
    if (parallelEligible && concurrentTask) {
      applyTaskOutcome(ctx.taskGraph, concurrentTask.id, { status: 'RUNNING' })
      branchWorldModel = WorldModel.fromJSON(ctx.worldModel.toJSON())
      const branchToolFn = ctx.toolExecutors[concurrentTask.id] ?? ctx.toolExecutors['default'] ?? (() => ({ completed: true }))
      const branchExecResult = await execute(
        { description: concurrentTask.description, change_type: 'read-only' },
        branchToolFn,
        {
          worldModel: branchWorldModel,
          evidenceStore: ctx.evidenceStore,
          taskGraph: ctx.taskGraph,
          currentTask: concurrentTask,
          memoryState: ctx.memoryState,
          beliefDepGraph: ctx.beliefDepGraph,
          controlState: ctx.controlState,
          diagnostics: ctx.diagnostics,
          failureDiagnostics: ctx.failureDiagnostics,
        },
      )
      branchExecSucceeded = branchExecResult.success
      if (branchExecSucceeded) {
        const branchEvidence = gatherEvidence(
          {
            id: `exec-${concurrentTask.id}-${ctx.stepsUsed}`,
            obs: `Task executed: ${concurrentTask.description}`,
            source: 'execution_engine',
            evidence_type: 'OBSERVATION',
            reliability: 'HIGH',
          },
          ctx.evidenceStore,
        )
        if (branchEvidence) {
          updateWorldModel(applyToolReliability(branchEvidence, ctx.evidenceStore, ctx.diagnostics), branchWorldModel, ctx.diagnostics)
        }
      }
    }

    // ─── SUB-STEP B ───────────────────────────────────────────────────────

    ctx.worldModel.incrementGenerationId()

    ctx.nodeExecutionOrder.push('gather_evidence')
    ctx.nodeExecutionOrder.push('apply_tool_reliability')
    ctx.nodeExecutionOrder.push('update_world_model_post_exec')
    if (execResult.success) {
      // Two distinct evidence items per successfully executed task — that a task ran, and
      // what it produced — so evidence_sufficiency's local-scope >=2 bar (verify.ts) is a
      // real threshold instead of one a fresh single-task turn can never clear (Phase 0.1 of
      // the harness layer activation plan).
      const executed = gatherEvidence(
        {
          id: `exec-${currentTask.id}-${ctx.stepsUsed}`,
          obs: `Task executed: ${currentTask.description}`,
          source: 'execution_engine',
          evidence_type: 'OBSERVATION',
          reliability: 'HIGH',
        },
        ctx.evidenceStore,
      )
      if (executed) {
        const capped = applyToolReliability(executed, ctx.evidenceStore, ctx.diagnostics)
        updateWorldModel(capped, ctx.worldModel, ctx.diagnostics)
      }

      const outcome = gatherEvidence(
        {
          id: `result-${currentTask.id}-${ctx.stepsUsed}`,
          obs: `Result: ${summariseExecutionOutput(execResult.output)}`,
          source: 'result_inspection',
          evidence_type: 'OBSERVATION',
          reliability: 'MEDIUM',
        },
        ctx.evidenceStore,
      )
      if (outcome) {
        const cappedOutcome = applyToolReliability(outcome, ctx.evidenceStore, ctx.diagnostics)
        updateWorldModel(cappedOutcome, ctx.worldModel, ctx.diagnostics)
      }

      // Phase 2, layer 2: escalate past the always-on baseline above — register a real
      // tool_reliability_envelope for consequential tools, or when estimate_voi flagged this
      // turn as evidence-poor — instead of every turn paying for it regardless of stakes.
      // AL5a: `consequentialTools` is now effect-class-derived (write/execute); the tools this turn
      // actually exercised keep driving this gate, exactly as before — `exercisedTools` falls back to
      // `consequentialTools` for a caller that predates AL5a.
      const gateTools = sig?.exercisedTools ?? sig?.consequentialTools
      const evidenceShouldEscalate = resolveGate(ctx.layerPolicy, 'evidence_escalation', (gateTools?.size ?? 0) > 0 || shouldGatherEvidence).on
      if (evidenceShouldEscalate) {
        for (const tool of gateTools ?? []) {
          if (!ctx.evidenceStore.tool_reliability_envelopes[tool]) {
            ctx.evidenceStore.tool_reliability_envelopes[tool] = {
              tool,
              max_observation_reliability: 'MEDIUM',
              max_conclusion_reliability: 'MEDIUM',
            }
          }
        }
        reportLayer(ctx, 'evidence_reasoning', true, `Cross-checking with ${Math.max(1, gateTools?.size ?? 0)} source(s) before answering.`)
      } else {
        reportLayer(ctx, 'evidence_reasoning', false, 'single low-stakes observation is sufficient')
      }

      // Phase 0.2: promote caller-extracted facts into real INFERENCE beliefs — the
      // updateWorldModel INFERENCE branch already exists but was never reached because no
      // call site ever passed evidence_type: 'INFERENCE'.
      const facts = ctx.factExtractor?.(ctx.objective) ?? []
      // Phase 2, layer 1: a consequential or multi-task turn still gets an auditable belief
      // trail even with no extracted fact — a plain LOW-risk single task stays observation-only.
      const worldModelShouldFire = facts.length > 0 || (sig?.taskCount ?? 1) > 1 || (sig?.riskLevel ?? 'LOW') !== 'LOW'
      if (worldModelShouldFire) {
        facts.forEach((fact: { statement: string; isNew?: boolean }, i: number) => {
          const factEvidence = gatherEvidence(
            {
              id: `fact-${currentTask.id}-${ctx.stepsUsed}-${i}`,
              obs: fact.statement,
              source: 'fact_extraction',
              evidence_type: 'INFERENCE',
              reliability: 'MEDIUM',
            },
            ctx.evidenceStore,
          )
          if (factEvidence) {
            const cappedFact = applyToolReliability(factEvidence, ctx.evidenceStore, ctx.diagnostics)
            updateWorldModel(cappedFact, ctx.worldModel, ctx.diagnostics, {
              statement: fact.statement,
              derived_from: [factEvidence.id],
            })
          }
        })
        // AL8b: the belief-trail condition is a policy gate; static ⇒ always true here (today).
        const trailGate = resolveGate(ctx.layerPolicy, 'belief_trail', true)
        if (facts.length === 0 && trailGate.on) {
          // No extracted fact, but the turn is consequential/multi-step enough to warrant a
          // trail — derive a belief from the task's own execution observation instead.
          const trailSource = executed ?? outcome
          if (trailSource && taskAccomplished) {
            const trailEvidence = gatherEvidence(
              {
                id: `belief-${currentTask.id}-${ctx.stepsUsed}`,
                obs: completedTrailStatement(currentTask.description, execResult.output),
                source: 'world_model_trail',
                evidence_type: 'INFERENCE',
                reliability: 'MEDIUM',
              },
              ctx.evidenceStore,
            )
            if (trailEvidence) {
              updateWorldModel(trailEvidence, ctx.worldModel, ctx.diagnostics, {
                statement: completedTrailStatement(currentTask.description, execResult.output),
                derived_from: outcome ? [trailSource.id, outcome.id] : [trailSource.id],
              })
            }
          }
        }
        // facts[0] is usually a prior-turn fact re-seeded for the contradiction checker's
        // benefit (see PersonalAssistant's factExtractor), not something that just happened —
        // only an isNew fact is worth surfacing as "Remembered: ...". A turn that carried
        // forward known facts without stating a new one reports fired=false, matching how the
        // Contradiction layer reports "checked — no conflicts found" rather than claiming a
        // false positive.
        const newFact = facts.find((f) => f.isNew)
        if (newFact) {
          reportLayer(ctx, 'world_model', true, `Remembered: ${newFact.statement}`)
        } else if (facts.length > 0) {
          reportLayer(ctx, 'world_model', false, `no new fact this turn — ${facts.length} known fact(s) carried forward`)
        } else if (!trailGate.on) {
          reportLayer(ctx, 'world_model', false, 'belief trail skipped by layer policy', trailGate)
        } else {
          reportLayer(ctx, 'world_model', true, 'recorded a belief trail for a multi-step/consequential turn', trailGate)
        }
      } else {
        reportLayer(ctx, 'world_model', false, 'single LOW-risk task, no durable fact stated — observation only')
      }
    }

    // Phase 2, layer 9: 5 of the 9 verification layers hardcode PASS whenever their tool
    // manifest entry is *absent* (isToolAvailable's default) rather than explicitly false —
    // for a personal-assistant turn (always a plain-reply-shaped task; nothing here is a real
    // write_file/pytest-checkable change) those layers should report an honest SKIPPED, not a
    // fabricated PASS. Respects any explicit entry the caller already set.
    for (const tool of ['pytest', 'integration_runner', 'consistency_checker', 'assumption_checker', 'goal_checker']) {
      if (!(tool in ctx.evidenceStore.tool_availability_manifest)) {
        ctx.evidenceStore.tool_availability_manifest[tool] = { available: false, fallback_tool: null }
      }
    }

    await judgeSemanticHypotheses(ctx)
    ctx.nodeExecutionOrder.push('update_diagnostics_post_exec')
    updateDiagnostics(ctx.worldModel, ctx.hypothesisSet, ctx.taskGraph, ctx.failureDiagnostics, ctx.beliefDepGraph, ctx.diagnostics)
    reevaluatePolicy(ctx)
    // The line above the execute step reports health from before this iteration's execution was recorded.
    // Say so again only if this iteration's execution changed the verdict — a failure that tips a run into
    // caution is otherwise not reported until the next iteration, if that iteration is ever reached.
    reportDiagnosticsHealth(ctx, true)

    // Semantic escalation layered on top of FailureModeLibrary's own exact-string-overlap
    // match() above — only when the exact match found nothing, there are symptoms and library
    // entries to check, the symptom set actually changed since the last attempt (avoids
    // re-asking the same question every iteration when nothing new happened), AND a real failure
    // has actually been recorded this run. That last condition didn't exist before the library
    // gained default seed entries (see initialize.ts): with an always-empty library,
    // `libraryEntries.length > 0` alone was already a de facto kill switch, so it went
    // unnoticed that "there's at least one observation" is true on almost any turn with a tool
    // call, seeded library or not — this is FAILURE match, not observation match.
    //
    // `failure_history` is only written by rollbackAndReplan, which runs AFTER this block — so on a task's FIRST failure the
    // history is still empty and the matcher never got to classify it, only a later one (a transient service error on a
    // single-task turn was never matched before it was already given up on). The failure this very iteration just recorded
    // (`!execResult.success`, its SYSTEM_ERROR observation already in the world model) counts too.
    // Only a failure of THIS task is worth a call: a task that never failed has nothing to classify (the check used to run on every
    // iteration once ANY failure had been recorded, so a recovered turn paid for a call per remaining task), and once the matcher
    // has produced a match for a task it is not asked about that task again (the retry that recovers has nothing left to classify).
    const thisTaskFailed = !execResult.success || ctx.failureDiagnostics.failure_history.some(f => f.context?.['task_id'] === currentTask.id)
    if (ctx.semanticFailureMatcher && hookOn(ctx, 'failure_match') && ctx.failureDiagnostics.matched_pattern === null && thisTaskFailed && !ctx.failureMatchedTaskIds.has(currentTask.id)) {
      const libraryEntries = ctx.failureDiagnostics.failure_mode_library.getEntries()
      const symptoms = ctx.worldModel.observations.map(o => o.content)
      if (symptoms.length > 0 && libraryEntries.length > 0 && symptoms.length !== ctx.lastFailureMatchSymptomCount) {
        ctx.lastFailureMatchSymptomCount = symptoms.length
        let semanticMatch: Awaited<ReturnType<NonNullable<LoopContext['semanticFailureMatcher']>>> = null
        try {
          semanticMatch = await ctx.semanticFailureMatcher(symptoms, libraryEntries)
        } catch {
          /* fails open: a throwing matcher means no semantic match */
        }
        if (semanticMatch) {
          ctx.failureMatchedTaskIds.add(currentTask.id)
          ctx.failureDiagnostics.matched_pattern = {
            ...semanticMatch,
            confidence: normalise(semanticMatch.confidence, DimensionType.match_confidence),
            strategy_affinity: resolveSemanticMatchStrategy(semanticMatch, libraryEntries),
          }
        }
      }
    }

    ctx.nodeExecutionOrder.push('resolve_control_state_b')
    resolveAndStamp(ctx)

    ctx.nodeExecutionOrder.push('verify')
    // Eval-only ablation (Phase C5): skipVerification never set outside the benchmark arm.
    const verifyResult: VerificationResult = ctx.skipVerification
      ? { layer_results: [], has_critical_failure: false, adversarial_passed: null, critical_failure_tiers: [] }
      : verify(
          execResult.output,
          ctx.successCriteria,
          ctx.worldModel.assumptions,
          ctx.evidenceStore,
          currentTask.risk_level,
          ctx.evidenceStore,
          ctx.worldModel,
          ctx.outputContract,
          ctx.hypothesisSet,
        )
    if (ctx.skipVerification) {
      reportLayer(ctx, 'verification', false, 'verification skipped (eval ablation)')
    } else {
      reportLayer(ctx, 'verification', true, verifyResult.has_critical_failure
        ? `verification failed: ${verifyResult.layer_results.find(lr => lr.status === 'FAIL')?.detail ?? 'unknown'}`
        : 'all applicable layers passed')
      notifyHost(() => ctx.onVerification?.(verifyResult))
    }

    ctx.nodeExecutionOrder.push('post_exec_gate')
    const postGatePassed = postExecGate(
      execResult.output,
      verifyResult,
      ctx.controlState,
      ctx.worldModel,
      ctx.diagnostics,
      ctx.failureDiagnostics,
      ctx.outputContract,
      controlStateResolverFor(ctx),
    )

    ctx.nodeExecutionOrder.push('update_task_state')
    if (ctx.experienceLearning) {
      const taskSucceeded = postGatePassed && execResult.success && taskAccomplished
      ctx.memoryState.journal.push(journalEntryFor({
        step: ctx.stepsUsed,
        strategy: ctx.strategyState.current_strategy,
        success: taskSucceeded,
        // '' for an unmatched failure — the same class buildStrategyOrdering looks up for it.
        failureClass: taskSucceeded ? undefined : (ctx.failureDiagnostics.matched_pattern?.failure_class ?? ''),
        output: execResult.output,
      }))
    }
    if (postGatePassed && execResult.success && taskAccomplished) {
      applyTaskOutcome(ctx.taskGraph, currentTask.id, { status: 'COMPLETE', fromExecutionLayer: true })
      ctx.lastCompletedTaskId = currentTask.id
      ctx.finalResult = execResult.output

      if (ctx.experienceStore.available) {
        ctx.experienceStore.updateExperienceStore(
          `${currentTask.id}-step-${ctx.stepsUsed}`,
          { task_id: currentTask.id, outcome: 'COMPLETE', step: ctx.stepsUsed },
        )
      }
      reportLayer(ctx, 'recovery', false, 'task completed — nothing to recover from')
    } else {
      // A failure from any other cause supersedes a stale "not accomplished" note.
      if (taskAccomplished) ctx.lastNotAccomplished = undefined
      ctx.nodeExecutionOrder.push('rollback_replan')
      // Phase 2, layer 10: a real per-task rollback hook instead of the no-op the harness ran
      // before — a caller can restore real state (e.g. a memoryState.rollback_points snapshot)
      // when a task actually fails, rather than this being dead plumbing.
      const rollbackFn = ctx.rollbackExecutors?.[currentTask.id] ?? ctx.rollbackExecutors?.['default']

      // Trajectory Supervisor (S2) — consult the async decider ONLY on a genuine stall,
      // exactly like loop.py's S1 wiring. cannotMakeProgress() here also primes
      // strategyState.stall_reason for the digest (rollbackAndReplan re-checks it anyway).
      let supervisorDirective: SupervisorDirective | null = null
      let supervisorOriginalAction: SupervisorDirective['action'] | null = null
      if (ctx.supervisorDecider && cannotMakeProgress(ctx.strategyState, ctx.failureDiagnostics)) {
        // cannotMakeProgress() above also primes strategyState.stall_reason for the digest.
        const digest = buildDigest(ctx.strategyState, ctx.failureDiagnostics, ctx.taskGraph, ctx.worldModel, {
          successCriteria: ctx.successCriteria,
        })
        supervisorDirective = await resolveSupervisorDirective(
          ctx.supervisorDecider,
          digest.toJSON(),
          ctx.onSupervisorDirective,
        )
        supervisorOriginalAction = supervisorDirective.action
        // GATHER_EVIDENCE (S5) — run the investigation now (findings merged into the
        // WorldModel), then let the directive fall through as CONTINUE so the ladder
        // proceeds over the new evidence. rollbackAndReplan only acts on
        // REDIRECT_STRATEGY / REFRAME_PLAN, so a coerced CONTINUE is inert to it.
        if (supervisorDirective.action === 'GATHER_EVIDENCE') {
          supervisorDirective = await resolveGatherEvidence(ctx.worldModel, supervisorDirective, ctx.runInvestigation)
        }
        // ABORT (S6) — the supervisor judges the run unrecoverable after redirection is
        // exhausted. Escalate immediately with a cannot_make_progress blocker carrying the
        // rationale; no rollback / replan this iteration. Q3 resolved (a): the supervisor
        // never touches resolveControlState() — this is a strategy / escalation move only,
        // exactly like loop.py's S6 wiring.
        if (supervisorDirective.action === 'ABORT') {
          ctx.strategyState.switch_triggers.push(
            `supervisor:ABORT ${supervisorDirective.rationale}`.trim().slice(0, 200),
          )
          throw new EscalationHalt({
            reason: 'cannot_make_progress',
            missing_info: ['clarification on how to proceed', 'revised success criteria'],
            current_task_summary:
              `${currentTask.description} | supervisor ABORT: ${supervisorDirective.rationale}`.trim().slice(0, 500),
            escalated_at: new Date().toISOString(),
          })
        }
        // ASK_USER (S3) — the supervisor needs a human decision. With a host askUser
        // capability and within the per-run cap, throw a structured `supervisor_question`
        // EscalationHalt (question + options on the blocker); the host surfaces it and
        // resumes with an answer (→ a user_clarification observation). Without the
        // capability, or past the cap, degrade to a plain cannot_make_progress escalation.
        // Escalation only — never a resolveControlState() write, exactly like ABORT.
        //
        // Q1 of the internal plan: the blocker is now built via
        // ask-question.ts's askQuestion() — the supervisor is one caller of that shared,
        // independently-flagged primitive, not its own inline question/options builder.
        // With ctx.askMode unset/'disabled' (DEFAULT_ASK_MODE, the default for the whole
        // rollout window), askQuestion() degrades to exactly the legacy blocker.question/
        // .options shape this branch built directly before Q1 — byte-identical output.
        if (supervisorDirective.action === 'ASK_USER' && supervisorDirective.question) {
          const q = supervisorDirective.question
          const withinCap = !!ctx.askUser && ctx.supervisorAskUserCount < SUPERVISOR_ASK_USER_CAP_M
          ctx.strategyState.switch_triggers.push(
            `supervisor:ASK_USER${withinCap ? '' : '->escalate'} ${supervisorDirective.rationale}`.trim().slice(0, 200),
          )
          if (withinCap) {
            ctx.supervisorAskUserCount += 1
            try {
              ctx.askUser!(q.toJSON())
            } catch {
              /* an observability handler must never break the run */
            }
            // 1 or 5+ options doesn't fit Q0's 2-4-option floor/ceiling — defensively drop
            // to a free-text-only AskQuestion rather than throwing on an LLM-authored
            // options list that doesn't fit the cap.
            const options =
              q.options.length >= MIN_OPTIONS_PER_QUESTION && q.options.length <= MAX_OPTIONS_PER_QUESTION
                ? q.options.map((label) => ({ label }))
                : undefined
            const askQuestionBatch: AskQuestion[] = [{ id: 'supervisor-ask', question: q.question, options }]
            askQuestion(askQuestionBatch, {
              reason: 'supervisor_question',
              missingInfo: ['answer to the supervisor question'],
              currentTaskSummary: `${currentTask.description} | supervisor question: ${q.question}`.trim().slice(0, 500),
              globalEnabled: ctx.askMode === 'enabled',
            })
          }
          throw new EscalationHalt({
            reason: 'cannot_make_progress',
            missing_info: ['clarification on how to proceed', 'revised success criteria'],
            current_task_summary:
              `${currentTask.description} | supervisor ASK_USER (no host): ${supervisorDirective.rationale}`
                .trim()
                .slice(0, 500),
            escalated_at: new Date().toISOString(),
          })
        }
      }

      // Trajectory Supervisor lever 1 (S8) — a REDIRECT_STRATEGY directive, or a
      // GATHER_EVIDENCE that actually ran its investigation, is a "retry this task
      // differently" signal. Tell rollbackAndReplan to re-queue the failed leaf if the
      // LOCAL replan would otherwise leave a one-node turn graph with nothing PENDING.
      const requeueLeafOnLocal =
        supervisorOriginalAction === 'REDIRECT_STRATEGY' ||
        (supervisorOriginalAction === 'GATHER_EVIDENCE' &&
          supervisorDirective?.rationale?.startsWith(INVESTIGATION_DONE_PREFIX) === true)

      const rollbackResult = rollbackAndReplan(
        currentTask,
        ctx.strategyState,
        ctx.failureDiagnostics,
        ctx.taskGraph,
        ctx.worldModel,
        ctx.callerState,
        ctx.experienceStore.available ? ctx.experienceStore : null,
        rollbackFn,
        supervisorDirective,
        requeueLeafOnLocal,
        ctx.experienceLearning === true,
        // Everything (retryFailedTask), or just this iteration's failure when the executor itself broke (retryFailedSystemErrors).
        ctx.retryFailedTask === true || retrySystemErrorOnce(ctx, currentTask.id, execResult),
      )
      // Adopt the recovery ladder's output — parity with loop.py (strategy_state /
      // task_graph reassigned after switch_strategy / apply_replan, loop.py:480-534).
      // Without this the strategy switch and a GLOBAL rebuild were computed and thrown
      // away: switch_count never advanced and cannotMakeProgress()'s strategy_loop /
      // stalled-completion edges could never trip in this loop.
      ctx.strategyState = rollbackResult.newStrategyState
      if (rollbackResult.replanScope === 'GLOBAL') ctx.taskGraph = rollbackResult.newTaskGraph
      reportLayer(ctx, 'recovery', true, `Trying a different approach — switched to "${rollbackResult.newStrategyState.current_strategy}" (${rollbackResult.replanScope ?? 'local'} replan)`)
      if (rollbackResult.failureModeSwitch) {
        const sw = rollbackResult.failureModeSwitch
        notifyHost(() => ctx.onFailureModeSwitch?.({ taskId: currentTask.id, ...sw }))
      }
      if (rollbackResult.learnedSwitch) {
        const sw = rollbackResult.learnedSwitch
        notifyHost(() => ctx.onLearnedStrategySwitch?.({ taskId: currentTask.id, ...sw }))
      }
    }

    // Reconcile the concurrent-task branch forked off above (layer 7) — done after this
    // task's own SUB-STEP B so both branches' independent WorldModel mutations are complete
    // before merging (reconcileParallelBranches' contract).
    if (branchWorldModel && concurrentTask) {
      const reconciled = reconcileParallelBranches(
        [
          { worldModel: ctx.worldModel, controlState: ctx.controlState },
          { worldModel: branchWorldModel, controlState: ctx.controlState },
        ],
        ctx.taskGraph,
        ctx.diagnostics,
        ctx.failureDiagnostics,
        ctx.evidenceStore,
        ctx.hypothesisSet,
        controlStateResolverFor(ctx),
        currentTask.parallel_write_domains.flatMap(
          (da): Array<[string, string]> => (concurrentTask.parallel_write_domains.map(db => [da, db])),
        ),
      )
      ctx.worldModel = reconciled.worldModel
      ctx.controlState.generation_id = reconciled.controlState.generation_id
      ctx.controlState.permission = reconciled.controlState.permission
      ctx.controlState.execution_mode = reconciled.controlState.execution_mode
      ctx.controlState.escalation = reconciled.controlState.escalation
      ctx.controlState.risk_estimate = reconciled.controlState.risk_estimate
      ctx.controlState.confidence_estimate = reconciled.controlState.confidence_estimate
      ctx.controlState.escalation_reason = reconciled.controlState.escalation_reason
      ctx.controlState.block_mask = [...reconciled.controlState.block_mask]
      ctx.controlState.notes = [...reconciled.controlState.notes]

      if (branchExecSucceeded && concurrentTask.status !== 'COMPLETE') {
        applyTaskOutcome(ctx.taskGraph, concurrentTask.id, { status: 'COMPLETE', fromExecutionLayer: true })
      } else if (concurrentTask.status === 'RUNNING') {
        applyTaskOutcome(ctx.taskGraph, concurrentTask.id, { status: 'PENDING', fromExecutionLayer: false })
      }
    }

    ctx.strategyState.completion_history.push(
      ctx.taskGraph.tasks.filter(t => t.status === 'COMPLETE').length,
    )
    ctx.strategyState.risk_state_history.push(riskSummary(ctx.controlState))

    if (ctx.stepsUsed >= Math.floor(0.8 * ctx.maxSteps)) {
      ctx.diagnostics.verification_health.feasibility = Math.min(
        ctx.diagnostics.verification_health.feasibility,
        BUDGET_WARNING_FLOOR,
      )
    }

    // Running out of budget with every task already COMPLETE is not a halt: nothing is left to do, and the loop only
    // needs one more pass to notice and finish. (It used to halt here, discarding a finished run's answer and asking
    // the user how to proceed on work that was done.)
    // A resumed run replays its interrupted step and reaches this check BEFORE the top of the next iteration would poll
    // for the user's answer to the budget question, so poll here first: "Continue" extends the limit, "Stop" cancels
    // what is left. (Only when the budget is actually spent and work remains — an ordinary iteration never gets here.)
    if (ctx.stepsUsed >= ctx.maxSteps && !nothingLeftToRun(ctx)) {
      const late = await pollCallerUpdates(ctx)
      if (late === RESTART_ITERATION) {
        resolveAndStamp(ctx)
        continue
      }
    }
    if (ctx.stepsUsed >= ctx.maxSteps && !nothingLeftToRun(ctx)) {
      const exhaust = escalateBudgetExhausted(ctx.stepsUsed, ctx.maxSteps)
      if (resolveAskMode({ globalEnabled: ctx.askMode === 'enabled' })) {
        askQuestion([buildBudgetExhaustedQuestion(ctx.stepsUsed)], {
          reason: 'budget_exhausted',
          missingInfo: exhaust.missing_info,
          currentTaskSummary: `Exhausted at step ${ctx.stepsUsed}`,
          globalEnabled: ctx.askMode === 'enabled',
        })
      }
      throw new EscalationHalt({
        reason: 'budget_exhausted',
        missing_info: exhaust.missing_info,
        current_task_summary: `Exhausted at step ${ctx.stepsUsed}`,
        escalated_at: new Date().toISOString(),
      })
    }

    yield toCheckpoint(ctx)
  }
}

/** Every task is COMPLETE, or was cancelled by the caller (blocked `goal_cancelled`) — nothing is left to run. */
function nothingLeftToRun(ctx: LoopContext): boolean {
  const tasks = ctx.taskGraph.tasks
  return tasks.length > 0 && tasks.every(t => t.status === 'COMPLETE' || (t.status === 'BLOCKED' && t.block_reason === 'goal_cancelled'))
}

/**
 * Polls the caller's update channel once (constraint changes, steering, a clarification answer). An answer to the budget
 * question is a CONTROL action, not a scope constraint: it is taken off the update here and acted on directly, so it
 * never reaches the constraint pipeline (which appended it as constraint text and let the task-graph revalidator drop
 * the very task the user asked to continue with, or invent a new one).
 */
async function pollCallerUpdates(ctx: LoopContext): Promise<Awaited<ReturnType<typeof checkCallerUpdates>>> {
  const channel: UpdateChannel = {
    poll: async () => {
      const update = await ctx.updateChannel.poll()
      return update ? takeBudgetAnswers(ctx, update) : update
    },
  }
  return checkCallerUpdates(ctx.callerState, channel, {
    worldModel: ctx.worldModel, hypothesisSet: ctx.hypothesisSet, taskGraph: ctx.taskGraph,
    diagnostics: ctx.diagnostics, failureDiagnostics: ctx.failureDiagnostics,
    evidenceStore: ctx.evidenceStore, outputContract: ctx.outputContract,
  })
}

/**
 * Acts on the user's answer to the budget_exhausted question (ask-question.ts's `buildBudgetExhaustedQuestion`) and removes
 * it from the update. Until now the answer was only appended to the caller's constraint text: picking "Continue with 10
 * more steps" changed nothing, so a resumed run halted again at once, and "Stop" did nothing either.
 *  - Continue: the step limit grows by DEFAULT_BUDGET_EXTENSION.
 *  - Stop and summarize: every task that is not already done is blocked (the same cancel a steering CANCEL_CURRENT
 *    uses), so the loop finishes with what exists.
 *  - Let me clarify the goal: no budget effect; the answer stays a constraint for the resumed run to read.
 * Options are recognised by the exact labels the builder produced, not by fuzzy text.
 */
function takeBudgetAnswers(ctx: LoopContext, update: CallerUpdate): CallerUpdate | null {
  const answers = update.pending_update.clarification_answers
  if (!Array.isArray(answers)) return update
  const template = buildBudgetExhaustedQuestion(0)
  const continueLabel = template.options?.[0]?.label
  const stopLabel = template.options?.[1]?.label
  const isBudget = (a: { questionId?: string }) => a.questionId === template.id
  const budget = (answers as Array<{ questionId?: string; selectedLabels?: string[] }>).filter(isBudget)
  if (budget.length === 0) return update
  for (const answer of budget) {
    if (!Array.isArray(answer.selectedLabels)) continue
    if (continueLabel !== undefined && answer.selectedLabels.includes(continueLabel)) ctx.maxSteps += DEFAULT_BUDGET_EXTENSION
    else if (stopLabel !== undefined && answer.selectedLabels.includes(stopLabel)) cancelTaskGraph(ctx.taskGraph)
  }
  const rest = (answers as Array<{ questionId?: string }>).filter((a) => !isBudget(a))
  if (rest.length === 0) return null
  return { ...update, pending_update: { ...update.pending_update, clarification_answers: rest } }
}

async function runMainLoopWithCheckpoints(
  ctx: LoopContext,
  options: HarnessRunOptions,
): Promise<{ status: 'completed' } | { status: 'paused'; checkpoint: HarnessCheckpoint }> {
  const gen = driveMainLoop(ctx)
  while (true) {
    const { value: checkpoint, done } = await gen.next()
    if (done) return { status: 'completed' }

    if (options.onCheckpoint) await options.onCheckpoint(checkpoint)
    if (options.shouldPause?.(checkpoint)) return { status: 'paused', checkpoint }
  }
}

async function drive(ctx: LoopContext, options: HarnessRunOptions): Promise<HarnessRunOutcome> {
  let outcome: HarnessRunOutcome
  try {
    outcome = await driveToCompletion(ctx, options)
  } catch (err) {
    // A halted run is the most informative one — learn from it, then let the halt propagate.
    learnFromRun(ctx)
    throw err
  }
  if (outcome.status !== 'paused') learnFromRun(ctx)
  return outcome
}

/** Cross-run learning from this run's journal (HarnessRunOptions.experienceLearning). Never throws: learning must not break a run. */
function learnFromRun(ctx: LoopContext): void {
  if (!ctx.experienceLearning || !ctx.experienceStore.available) return
  try {
    learnFromJournal(ctx.memoryState.journal, ctx.experienceStore, {
      rule: ctx.experienceLearningRule,
      runId: ctx.runId,
      onEvent: ctx.onStrategyEvent,
    })
  } catch {
    /* a failing store must not turn a finished run into a failed one */
  }
}

async function driveToCompletion(ctx: LoopContext, options: HarnessRunOptions): Promise<HarnessRunOutcome> {
  const first = await runMainLoopWithCheckpoints(ctx, options)
  if (first.status === 'paused') return first

  // Phase 2, layer 11: the adversarial lens is the expensive BFS-over-beliefs one — worth
  // paying for on a consequential or multi-step turn, not a one-line factual answer. The
  // implementer/reviewer lenses always run (cheap, and now accurate once beliefs are real).
  const sigForReview = ctx.complexitySignal
  const adversarialGate = resolveGate(ctx.layerPolicy, 'reviewer_adversarial',
    (sigForReview?.riskLevel ?? 'LOW') !== 'LOW' || (sigForReview?.taskCount ?? 1) >= 3)
  const runAdversarialLens = adversarialGate.on

  // Eval-only ablation (Phase C6): skipReviewerPass never set outside the benchmark arm. Unlike
  // C5's skipVerification (a mandatory per-iteration main-loop step, always pushed to
  // nodeExecutionOrder even when its work is skipped), the reviewer pass is a post-loop step run
  // at most once (twice if a task reopens) per drive() call — skipping it means it genuinely never
  // ran this turn, so 'reviewer_pass'/'reviewer_pass_2' are omitted from nodeExecutionOrder
  // entirely rather than pushed-but-empty.
  if (!ctx.skipReviewerPass) {
    ctx.nodeExecutionOrder.push('reviewer_pass')
    const reviewPassResult = await reviewerPass(
      ctx.worldModel, ctx.successCriteria, ctx.failureDiagnostics, ctx.beliefDepGraph,
      ctx.depGraphBudget, ctx.hypothesisSet, ctx.taskGraph, ctx.diagnostics, ctx.evidenceStore, ctx.propagationQueue,
      runAdversarialLens, hookOn(ctx, 'criterion_coverage') ? ctx.semanticCriterionCoverage : undefined, ctx.isCheckableCriterion,
    )
    const allFindings = [...reviewPassResult.implementer_findings, ...reviewPassResult.reviewer_findings, ...reviewPassResult.adversarial_findings]
    reportLayer(ctx, 'reviewer_pass', allFindings.length > 0, allFindings.length > 0 ? allFindings[0] : 'self-review found nothing to flag')

    // Phase I / INV-18: hand this pass's verdict to the *next* resolveAndStamp() call —
    // one-shot, single-slot (overwrites, never accumulates). The only reachable "next
    // iteration" within one drive() call is the reopened-tasks second main-loop pass below;
    // if nothing reopened, this just rides along in the final checkpoint unconsumed.
    ctx.pendingReviewerVerdict = reviewPassResult.pending_verdict

    // Make a finding act: at the end of a run, with nothing already reopened, the host may turn the verdict into a
    // revision note. The last task to complete is reopened so it runs once more (the reopened-tasks pass below), and the
    // host delivers the note to whatever produces the answer. At most once per run; every failure path is a no-op.
    const revisionReopened = maybeReopenForReviewerRevision(ctx, reviewPassResult)
    if (revisionReopened) reviewPassResult.reopened_task_ids.push(revisionReopened)

    if (reviewPassResult.reopened_task_ids.length > 0) {
      for (const taskId of reviewPassResult.reopened_task_ids) {
        const task = ctx.taskGraph.getTask(taskId)
        if (task) {
          task.status = 'PENDING'
          ctx.taskGraph.changed = true
        }
      }

      const second = await runMainLoopWithCheckpoints(ctx, options)
      if (second.status === 'paused') return second

      ctx.nodeExecutionOrder.push('reviewer_pass_2')
      const reviewPassResult2 = await reviewerPass(
        ctx.worldModel, ctx.successCriteria, ctx.failureDiagnostics, ctx.beliefDepGraph,
        ctx.depGraphBudget, ctx.hypothesisSet, ctx.taskGraph, ctx.diagnostics, ctx.evidenceStore, ctx.propagationQueue,
        runAdversarialLens, hookOn(ctx, 'criterion_coverage') ? ctx.semanticCriterionCoverage : undefined, ctx.isCheckableCriterion,
      )
      ctx.pendingReviewerVerdict = reviewPassResult2.pending_verdict
    }
  } else {
    reportLayer(ctx, 'reviewer_pass', false, 'reviewer pass skipped (eval ablation)')
  }

  ctx.nodeExecutionOrder.push('output_validation')
  const judge = ctx.semanticConstraintJudge
  let validationResult = outputValidation(ctx.finalResult, ctx.outputContract, ctx.callerState, { skipCallerConstraints: judge !== undefined || (ctx.stalledFallbackText !== undefined && ctx.finalResult === ctx.stalledFallbackText) })
  let violated = await judgeConstraints(ctx, judge)
  if (violated.length > 0) {
    const reopened = maybeReopenForConstraintRevision(ctx, violated)
    if (reopened) {
      const task = ctx.taskGraph.getTask(reopened)
      if (task) {
        task.status = 'PENDING'
        ctx.taskGraph.changed = true
      }
      const again = await runMainLoopWithCheckpoints(ctx, options)
      if (again.status === 'paused') return again
      ctx.nodeExecutionOrder.push('output_validation_2')
      validationResult = outputValidation(ctx.finalResult, ctx.outputContract, ctx.callerState, { skipCallerConstraints: judge !== undefined || (ctx.stalledFallbackText !== undefined && ctx.finalResult === ctx.stalledFallbackText) })
      violated = await judgeConstraints(ctx, judge)
    }
  }
  // A host that can show a note (it opted into the revision) gets the answer back with the violation attached rather than a
  // thrown error: the model's reply is still the best answer there is, and the user should be told what it did not meet.
  const unresolved = violated.length > 0 && ctx.onConstraintRevision ? violated : undefined
  if (violated.length > 0 && !unresolved) {
    throw new OutputContractError(
      'caller_specific_constraints',
      violated.map(v => `caller_specific_constraints: constraint violated: "${v.constraint}"${v.reason ? ` (${v.reason})` : ''}`),
    )
  }

  // propagateBeliefs available for introspection but not part of the return
  void propagateBeliefs

  const result: HarnessRunResult = {
    finalResult: ctx.finalResult,
    outputValidation: validationResult,
    stepsUsed: ctx.stepsUsed,
    initResult: toInitResultShape(ctx),
    nodeExecutionOrder: ctx.nodeExecutionOrder,
    ...(unresolved ? { unresolvedConstraintViolations: unresolved } : {}),
  }

  // Always emit one final checkpoint on completion so a caller persisting
  // checkpoints ends up with a snapshot of the terminal state, not just the
  // last mid-loop one.
  if (options.onCheckpoint) await options.onCheckpoint(toCheckpoint(ctx))

  return { status: 'complete', result }
}

export class HarnessRuntime {
  async run(
    objective: string,
    successCriteria: string[],
    options: HarnessRunOptions = {},
  ): Promise<HarnessRunOutcome> {
    const runId = options.runId ?? generateRunId()
    const ctx = buildInitialContext(objective, successCriteria, options, runId)
    return drive(ctx, options)
  }

  async resume(checkpoint: HarnessCheckpoint, options: HarnessRunOptions = {}): Promise<HarnessRunOutcome> {
    const ctx = buildResumedContext(checkpoint, options)
    return drive(ctx, options)
  }
}
